5	import java.security.NoSuchAlgorithmException;
6	import java.util.Collection;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's deterministic {@code householdId} and detects household membership.
12	 * Owners that carry the same normalized last name and postcode belong to the same
13	 * household, so they automatically share the same id.
14	 */
15	final class Households {
16	
17	    private Households() {
18	    }
19	
20	    /** Trim, collapse internal whitespace and lower-case a value for comparison. */
21	    private static String normalize(String value) {
22	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
23	    }
24	
25	    /**
26	     * The stable household id for an owner: the first 12 hex characters of SHA-256 over
27	     * {@code (normalizedLastName + '|' + postcode)}. Owners with the same last name and
28	     * postcode share it automatically.
29	     */
30	    static String householdId(Owner owner) {
31	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
32	        return sha256hex("V2|" + normalize(owner.getLastName()) + "|" + postcode).substring(0, 12);
33	    }
34	
35	    /** How many of the given owners belong to the candidate's household (share its household id). */
36	    static long memberCount(Collection<Owner> owners, Owner candidate) {
37	        String id = householdId(candidate);
38	        return owners.stream().filter(o -> id.equals(householdId(o))).count();
39	    }
40	
41	    /** True when an existing owner shares the candidate's last name AND address, i.e. the
42	     *  same household id and the same (normalized) address line. */
43	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
44	        String id = householdId(candidate);
45	        String address = normalize(candidate.getAddressLine1());
46	        return existing.stream().filter(o -> !o.isDeleted())
47	            .anyMatch(o -> id.equals(householdId(o)) && address.equals(normalize(o.getAddressLine1())));
48	    }
49	
50	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code s}. */
51	    private static String sha256hex(String s) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
54	            StringBuilder sb = new StringBuilder(digest.length * 2);
55	            for (byte b : digest) {
56	                sb.append(String.format("%02x", b));
57	            }
58	            return sb.toString();
59	        }
60	        catch (NoSuchAlgorithmException e) {
61	            throw new IllegalStateException(e);
62	        }
63	    }
64	}
