10	/**
11	 * De-duplicates a computed customerCode against existing owners. When the base code
12	 * collides, appends {@code '-<n>'} with the smallest {@code n >= 2} that is free.
13	 */
14	final class UniqueCustomerCodes {
15	
16	    private UniqueCustomerCodes() {
17	    }
18	
19	    /** The base code if free, otherwise {@code base + "-<n>"} for the smallest free n >= 2. */
20	    static String deduplicate(Collection<Owner> existing, String base) {
21	        Set<String> taken = existing.stream()
22	            .map(Owner::getCustomerCode)
23	            .filter(Objects::nonNull)
24	            .collect(Collectors.toSet());
25	        if (!taken.contains(base)) {
26	            return base;
27	        }
28	        int n = 2;
29	        while (taken.contains(base + "-" + n)) {
30	            n++;
31	        }
32	        return base + "-" + n;
33	    }
34	}
