19	import java.util.Map;
20	
21	/**
22	 * Normalises a postal address to a canonical form for storage and comparison.
23	 *
24	 * <p>Whitespace is trimmed and collapsed, the value is upper-cased, and common
25	 * street-type abbreviations are expanded as whole words ({@code ST -> STREET},
26	 * {@code RD -> ROAD}, {@code AVE -> AVENUE}). A value that is blank (only
27	 * whitespace) normalises to the empty string.
28	 */
29	public abstract class Addresses {
30	
31	    private static final Map<String, String> ABBREVIATIONS =
32	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
33	
34	    /**
35	     * @param raw the raw address input, may be {@code null}
36	     * @return the normalised address, or {@code null} when {@code raw} is {@code null}
37	     */
38	    public static String normalize(String raw) {
39	        if (raw == null) {
40	            return null;
41	        }
42	        StringBuilder sb = new StringBuilder();
43	        for (String token : raw.trim().toUpperCase().split("\\s+")) {
44	            if (token.isEmpty()) {
45	                continue;
46	            }
47	            if (sb.length() > 0) {
48	                sb.append(' ');
49	            }
50	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
51	        }
52	        return sb.toString();
53	    }
54	
55	    /**
56	     * Composes the canonical address, preferring the structured fields. When
57	     * {@code addressLine1} is non-blank the result is its normalized form, with a
58	     * single space and the normalized {@code addressLine2} appended when that is
59	     * present; otherwise the normalized flat {@code address} is returned.
60	     *
61	     * @param addressLine1 the structured primary line, may be {@code null}
62	     * @param addressLine2 the structured secondary line, may be {@code null}
63	     * @param address the flat address, may be {@code null}
64	     * @return the composed, normalized address
65	     */
66	    public static String compose(String addressLine1, String addressLine2, String address) {
67	        String line1 = normalize(addressLine1);
68	        if (line1 == null || line1.isEmpty()) {
69	            return normalize(address);
70	        }
71	        String line2 = normalize(addressLine2);
72	        return (line2 == null || line2.isEmpty()) ? line1 : line1 + " " + line2;
73	    }
74	
75	}
