7	/**
8	 * Business-day helper: a weekend or public-holiday date rolls forward to the next
9	 * non-holiday business day; ordinary weekdays are returned unchanged.
10	 */
11	public final class BusinessDays {
12	
13	    /** Fixed public holidays the roll skips. */
14	    private static final Set<LocalDate> HOLIDAYS = Set.of(
15	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
16	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
17	        LocalDate.parse("2026-12-28"));
18	
19	    private BusinessDays() {
20	    }
21	
22	    /** Roll weekends and public holidays forward to the next business day. */
23	    public static LocalDate rollForward(LocalDate date) {
24	        while (!isBusinessDay(date)) {
25	            date = date.plusDays(1);
26	        }
27	        return date;
28	    }
29	
30	    private static boolean isBusinessDay(LocalDate date) {
31	        DayOfWeek day = date.getDayOfWeek();
32	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
33	    }
34	}
