5	/**
6	 * Derives an owner's unified {@code memberId} formatted {@code '<REGION><FY><HASH8><CHK>'}:
7	 * the region and 8-hex identity carried by the owner's (de-duplicated) customer code, the
8	 * two-digit fiscal year of the registration date, and a single trailing Luhn check digit
9	 * computed over the digits of {@code <REGION><FY><HASH8>}. Because it reads from the stored
10	 * customer code, collision handling on that code carries through to the member id.
11	 */
12	public final class MemberIds {
13	
14	    private MemberIds() {
15	    }
16	
17	    /** The {@code '<REGION><FY><HASH8><CHK>'} member id, or {@code null} when unavailable. */
18	    public static String of(Owner owner) {
19	        String code = owner.getCustomerCode();
20	        if (code == null || owner.getRegistrationDate() == null) {
21	            return null;
22	        }
23	        int dash = code.indexOf('-');
24	        String region = (dash < 0 ? code : code.substring(0, dash)) + "V2";
25	        String hash = dash < 0 ? "" : code.substring(dash + 1);
26	        String stem = region + String.format("%02d", FiscalYears.yearOfCentury(owner.getRegistrationDate())) + hash;
27	        return stem + Luhn.checkDigit(stem);
28	    }
29	}
