3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Membership points and the level they map to. Points start at 0 and gain +2 for a
7	 * present email, +1 when the owner has no namesake, +2 for a household of 3 or more and
8	 * +3 for tenure over 365 days; the total maps to a level of 1 (0-1), 2 (2-3), 3 (4-5)
9	 * or 4 (6 or more).
10	 */
11	public final class Membership {
12	
13	    private Membership() {
14	    }
15	
16	    /** Total membership points for {@code owner} given its household and tenure flags. */
17	    public static int points(Owner owner, boolean largeHousehold, boolean longTenure) {
18	        int points = 0;
19	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
20	            points += 2;
21	        }
22	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
23	            points += 1;
24	        }
25	        if (largeHousehold) {
26	            points += 2;
27	        }
28	        if (longTenure) {
29	            points += 3;
30	        }
31	        return points;
32	    }
33	
34	    /** The membership level that {@code points} maps to: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6+). */
35	    public static int level(int points) {
36	        if (points >= 6) {
37	            return 4;
38	        }
39	        if (points >= 4) {
40	            return 3;
41	        }
42	        if (points >= 2) {
43	            return 2;
44	        }
45	        return 1;
46	    }
47	}
